// What a report names in place of a person, when the party is not a wallet.
//
// Deliberately NOT an EncryptablePersonalInfo with invented fields: a regulator reading a report
// has to be able to tell a real identity from a contract, and a fake person is indistinguishable
// from a real one once encrypted.  SuspiciousTransaction carries a party kind alongside this so the
// reader knows which of the two descriptors to decrypt.
type EncryptableContractInfo struct {
	// Stands in for EncryptablePersonalInfo.Nonce when building the report's amount nonce.  The
	// address is public and stable, which is all that nonce needs to be.
	Nonce   string `protobuf:"bytes,1,opt,name=Nonce,proto3" json:"Nonce,omitempty"`
	Address string `protobuf:"bytes,2,opt,name=Address,proto3" json:"Address,omitempty"`
	// 0 for a party that is not a wasm contract.  Recorded so a report says which code was running
	// at the time -- a later migration cannot retroactively change what was reported.
	CodeID uint64 `protobuf:"varint,3,opt,name=CodeID,proto3" json:"CodeID,omitempty"`
	// the governance-recorded justification from the whitelist entry
	Reason string `protobuf:"bytes,4,opt,name=Reason,proto3" json:"Reason,omitempty"`
}

